<div class="welcome-row"><div><div class="form-kicker">ENTRE SUAS CONTAS</div><h1>Transferências</h1><p class="page-subtitle">Movimente seu dinheiro sem contar como receita ou despesa.</p></div></div>
<?php if(!empty($errors)): ?><div class="alert error"><?=e(implode(' ',$errors))?></div><?php endif; ?>
<div class="transfer-layout"><section class="panel editor-panel"><div class="panel-head"><div><h3>Nova transferência</h3><p>Saída e entrada são registradas como uma operação única.</p></div></div><?php if(count($accounts)<2): ?><div class="inline-note">Cadastre pelo menos duas contas ativas para transferir. <a href="/accounts">Gerenciar contas</a></div><?php else: ?><form method="post" action="/transfers/save" class="data-form single"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Conta de origem<select name="source_account_id" required><?php foreach($accounts as $account): ?><option value="<?=(int)$account['id']?>"><?=e($account['name'])?></option><?php endforeach; ?></select></label><label>Conta de destino<select name="destination_account_id" required><?php foreach($accounts as $account): ?><option value="<?=(int)$account['id']?>" <?=isset($accounts[1])&&$account['id']===$accounts[1]['id']?'selected':''?>><?=e($account['name'])?></option><?php endforeach; ?></select></label><label>Valor<input name="amount" inputmode="decimal" required placeholder="0,00"></label><label>Data<input type="date" name="transfer_date" required value="<?=date('Y-m-d')?>"></label><label>Descrição<input name="description" maxlength="140" value="Transferência entre contas"></label><label>Observação<input name="notes" maxlength="500"></label><button class="button primary">Confirmar transferência</button></form><?php endif; ?></section>
<section class="panel statement-panel"><div class="panel-head"><div><h3>Histórico</h3><p>Transferências recentes</p></div></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Movimento</th><th>Contas</th><th class="right">Valor</th></tr></thead><tbody><?php foreach($transfers as $transfer): ?><tr><td><?=e(date('d/m/Y',strtotime($transfer['transfer_date'])))?></td><td><?=e($transfer['description'])?></td><td><?=e($transfer['source_name'])?> → <?=e($transfer['destination_name'])?></td><td class="right"><?=money((int)$transfer['amount'])?></td></tr><?php endforeach; ?><?php if(!$transfers): ?><tr><td colspan="4" class="table-empty">Nenhuma transferência registrada.</td></tr><?php endif; ?></tbody></table></div></section></div>
